-- Varikotsele (HARD) amaliy test bankini to'ldirish — 50 ta savol,
-- HTML maqola (ta'rif, epidemiologiya, patofiziologiya, klinik, diagnostika, davolash, asoratlar) asosida.
-- Amaliy test bo'limi shulardan random 20 tasini shuffle qilib chiqaradi.
-- Variantlar uzunligi muvozanatlangan (uzunlik teli yo'q).
UPDATE public.dars_tarkibi
SET savollar_banki = $savollar$[
{"savol":"Varikosele nima sababli yuzaga keladi?","variantlar":["Urug' tizimchasi arteriya bosimining keskin oshishi natijasida","Venoz klapanlar yetishmovchiligi natijasida qon reflyuksi","Limfa tomirlarining tiqilib, drenajning buzilishi natijasida","Urug' bezi to'qimasining surunkali bakterial yallig'lanishi"],"togri":1,"izoh":"Varikosele venalar klapanlarining yetishmovchiligi natijasida vena qonining orqaga qaytishi (venoz reflyuks) tufayli yuzaga keladi."},
{"savol":"Dubin-Amelar tasnifi bo'yicha, faqat instrumental tekshiruvda (Dopler UTT) aniqlanadigan, palpatsiya qilinmaydigan varikosele qaysi daraja deyiladi?","variantlar":["I-daraja (Valsalvada palpatsiya qilinadigan)","II-daraja (tinch holatda palpatsiya qilinadigan)","Subklinik (faqat Dopler UTTda aniqlanadigan)","III-daraja (ko'zga ko'rinadigan yirik shakl)"],"togri":2,"izoh":"Subklinik varikosele palpatsiya qilinmaydi va ko'rinmaydi, faqat Dopler UTT orqali aniqlanadi."},
{"savol":"I-daraja (yengil) varikosele qanday aniqlanadi?","variantlar":["Tinch, dam olgan holatda ham ko'zga yaqqol ko'rinadi","Faqat tik turib Valsalva sinamasi vaqtida palpatsiya qilinadi","Faqat gorizontal yotgan holatda qo'l bilan palpatsiya qilinadi","Hech qanday holatda umuman palpatsiya qilinmaydi (yashirin)"],"togri":1,"izoh":"I-daraja — faqat Valsalva sinamasi (kuchanish) vaqtida, tik turgan holatda palpatsiya qilinadi."},
{"savol":"II-daraja (o'rtacha) varikosele haqida qaysi gap to'g'ri?","variantlar":["Faqat Doppler UTT tekshiruvida aniqlanadigan yashirin shakl","Valsalvasiz ham palpatsiya qilinadi, lekin ko'zga ko'rinmaydi","Ko'z bilan aniq ko'rinadigan yirik venalar to'plami shaklida","Faqat o'smir yoshdagi bolalarda uchraydigan o'ziga xos shakl"],"togri":1,"izoh":"II-daraja Valsalva sinamasisiz ham qo'l bilan palpatsiya qilinadi, ammo ko'zga ko'rinmaydi."},
{"savol":"III-daraja (og'ir) varikosele qanday tavsiflanadi?","variantlar":["Faqat ultratovush tekshiruvida (USI) ko'rinadigan yashirin shakl","Moshonka terisi orqali ko'rinadi va oson palpatsiya qilinadi","Faqat Valsalva sinamasi paytida qo'l bilan aniqlanadigan shakl","Hech qanday tashqi yoki instrumental belgi bermaydigan shakl"],"togri":1,"izoh":"III-daraja eng og'ir shakl bo'lib, ko'z bilan ko'rinadi ('qurt to'plami' ko'rinishi) va osongina palpatsiya qilinadi."},
{"savol":"Varikosele necha foiz hollarda chap tomonda uchraydi?","variantlar":["~50%","~90%","~25%","~10%"],"togri":1,"izoh":"Varikosele taxminan 90% hollarda chap tomonlama uchraydi, bu anatomik sabablarga bog'liq."},
{"savol":"Subklinik varikoseleni davolash bo'yicha klinik eslatmaga ko'ra nima to'g'ri?","variantlar":["Albatta zudlik bilan jarrohlik aralashuvi talab qilinadi","Reproduktiv salohiyatni yaxshilamaydi, odatda kuzatiladi","Faqat uzoq muddatli antibiotik terapiyasi bilan davolanadi","Aniqlangan zahoti darhol embolizatsiya qilinishi kerak bo'ladi"],"togri":1,"izoh":"Ko'pchilik tadqiqotlar subklinik varikoseleni davolash fertillikni sezilarli yaxshilamasligini ko'rsatadi, shu sabab odatda kuzatiladi."},
{"savol":"Izolyatsiyalangan o'ng tomonlama varikosele aniqlansa, ayniqsa keskin boshlangan bo'lsa, birinchi navbatda nimani inkor etish zarur?","variantlar":["Qandli diabet va uning asoratlarini birinchi navbatda","Retroperitoneal patologiyani (masalan, buyrak o'smasini)","Oshqozon-ichak yarasi kasalligini birinchi navbatda inkor","Bronxial astma va nafas yo'llari patologiyasini birinchi"],"togri":1,"izoh":"O'ng tomonlama izolyatsiyalangan varikosele kamdan-kam uchraydi va retroperitoneal massa (masalan buyrak hujayrali karsinoma) tomonidan venoz drenajning bosilishidan shubhalanish kerak."},
{"savol":"Umumiy erkaklar populyatsiyasida varikoselening tarqalish chastotasi taxminan qancha?","variantlar":["~5%","~15%","~50%","~75%"],"togri":1,"izoh":"Umumiy erkaklar populyatsiyasida varikosele taxminan 15% (har 5-6 erkakdan 1 tasi) uchraydi."},
{"savol":"Ikkinchi darajali (sekundar) infertillik bilan murojaat qiluvchilarda varikosele chastotasi qancha?","variantlar":["~10%","~35%","75-81%","~5%"],"togri":2,"izoh":"Sekundar infertillik bilan murojaat qiluvchilarda varikosele chastotasi 75-81% gacha yetadi."},
{"savol":"Infertil erkaklarning umumiy qancha qismida varikosele aniqlanadi?","variantlar":["Atigi 5-10% — juda kam qismida uchraydi","1/3 dan 1/2 gacha (taxminan 33-50%) qismida","90% dan ortiq — deyarli barcha bemorlarda","Deyarli hech kimda uchramaydi, juda nodir"],"togri":1,"izoh":"Infertil erkaklarning taxminan 1/3 dan 1/2 gachasida (33-50%) varikosele aniqlanadi."},
{"savol":"Chap urug' venasi chap buyrak venasiga qanday burchak ostida va qaysi balandlikda quyiladi?","variantlar":["Qiya burchak ostida, o'ng tomonga nisbatan pastroqda","To'g'ri burchak ostida, o'ngdagidan 8-10 sm yuqorida","Spiral (buralgan) shaklda buyrak venasiga quyiladi","Bevosita pastki kovak venaga to'g'ridan-to'g'ri quyiladi"],"togri":1,"izoh":"Chap urug' venasi chap buyrak venasiga to'g'ri burchak ostida, o'ng tomondagidan 8-10 sm yuqorida quyiladi — bu uzunroq gidrostatik bosim ustunini yaratadi."},
{"savol":"O'ng urug' venasining pastki kovak venaga qiya burchak ostida quyilishi nimani ta'minlaydi?","variantlar":["Venadagi qon bosimini sezilarli darajada oshirib beradi","'Tabiiy klapan' effektini yaratib reflyuksdan himoya qiladi","Aksincha venoz turg'unlikni yanada kuchaytirib yuboradi","Klinik jihatdan hech qanday amaliy ahamiyatga ega emas"],"togri":1,"izoh":"O'ng tomondagi qiya burchak 'tabiiy klapan' vazifasini bajarib, reflyuksning oldini oladi — shu sabab varikosele o'ng tomonda kamroq uchraydi."},
{"savol":"Varikoseleda genetik moyillik haqida qaysi fikr to'g'ri?","variantlar":["Genetik omil bilan hech qanday bog'liqlik aniqlanmagan","Birinchi darajali qarindoshlarda bu holat ko'proq uchraydi","Faqat ona tomonidan naslga o'tuvchi irsiy kasallikdir","Faqat ayol jinsi vakillarida namoyon bo'ladigan holatdir"],"togri":1,"izoh":"Varikoseleli erkaklarning birinchi darajali qarindoshlarida bu holat ko'proq uchraydi, bu venoz klapan defektiga genetik moyillik borligini ko'rsatadi."},
{"savol":"Pampiniform pleksusning normal fiziologik vazifasi nima?","variantlar":["Yetilgan spermatozoidlarni vaqtincha to'plab saqlash","Qarama-qarshi oqim orqali moshonka haroratini pasaytirish","Asosiy erkaklik gormoni — testosteronni ishlab chiqarish","Qonni filtrlab, birlamchi siydik hosil qilishda ishtirok"],"togri":1,"izoh":"Pampiniform pleksus qarama-qarshi oqim issiqlik almashinuvini ta'minlab, moshonka haroratini tana haroratidan 2-4°C past saqlaydi — bu spermatogenez uchun zarur."},
{"savol":"Varikoselede intratestikulyar harorat nima sababli ko'tariladi?","variantlar":["Urug' bezidan ko'p miqdorda qon ketishi (yo'qotish) tufayli","Issiqlik almashinuvi (counter-current) mexanizmi buzilgani uchun","Surunkali bakterial infeksiya va yallig'lanish jarayoni tufayli","Gormonlar sintezining keskin oshib ketishi natijasida"],"togri":1,"izoh":"Varikoselede qarama-qarshi oqim issiqlik almashinuvi mexanizmi buziladi, natijada intratestikulyar harorat ko'tariladi va spermatogenez bevosita buziladi."},
{"savol":"Venoz turg'unlik (venous stasis) urug' bezida nimaga olib keladi?","variantlar":["Qon bosimining pasayishi va harorat tushishiga olib keladi","Gipoksiya va toksik metabolitlarning to'planishiga olib keladi","Mahalliy haroratning sezilarli pasayishiga olib keladi","Urug' bezida hech qanday sezilarli o'zgarish keltirmaydi"],"togri":1,"izoh":"Qonning turg'un holda to'planishi urug' bezida gipoksiya va toksik metabolitlarning to'planishiga olib keladi."},
{"savol":"Oksidativ stress spermatozoidlarga qanday ta'sir qiladi?","variantlar":["Spermatozoidlar harakatchanligini aksincha oshirib yuboradi","DNK fragmentatsiyasini kuchaytirib apoptozga moyillik oshiradi","Spermatozoidlar hajmi va o'lchamini kattalashtirib yuboradi","Spermatozoidlarga umuman hech qanday ta'sir ko'rsatmaydi"],"togri":1,"izoh":"Varikoseleli bemorlarning urug'ida yuqori oksidativ stress spermatozoidlar DNKsining fragmentatsiyasini kuchaytiradi va apoptozni oshiradi."},
{"savol":"Quyidagilardan qaysi biri varikoselening qo'shimcha patofiziologik mexanizmlariga kiradi?","variantlar":["Spermatozoidlarda aneuploidiyaga moyillikning oshishi","Qon guruhi va rezus omilning o'zgarib ketishi holati","Suyak to'qimasi zichligining kamayib zararlanishi holati","Ko'z to'r pardasining shikastlanib ko'rish pasayishi holati"],"togri":0,"izoh":"Boshqa mexanizmlar qatorida spermatozoidlarda aneuploidiyaga moyillik, hujayra ichi metabolik buzilish va apoptozga aloqador mikroRNK darajasining oshishi kiradi."},
{"savol":"Yirik varikoseleler kichiklariga nisbatan qanday ta'sir ko'rsatadi?","variantlar":["Kichiklariga nisbatan ancha kamroq zararlanishga olib keladi","Odatda kichiklariga nisbatan ko'proq zararlanishga olib keladi","Kattaligidan qat'i nazar hech qanday farq keltirib chiqarmaydi","Faqat estetik (tashqi ko'rinish) muammosini tug'diradi xolos"],"togri":1,"izoh":"Yirikroq varikoseleler odatda kichikroqlariga nisbatan ko'proq urug' bezi zararlanishiga olib keladi."},
{"savol":"Uzoq muddatli varikosele natijasida urug' bezida qanday o'zgarishlar yuzaga keladi?","variantlar":["Hajmi kattalashadi va spermatogenez faolligi kuchayadi","Atrofiya, spermatogenez pasayishi, Leydig funksiyasi buziladi","Umuman hech qanday tuzilmaviy o'zgarish yuzaga kelmaydi","Faqat tashqi rangi o'zgaradi, funksiyasi saqlanib qoladi"],"togri":1,"izoh":"Progressiv, davomiylikka bog'liq zararlanish natijasida urug' bezi atrofiyasi, spermatogenez pasayishi va androgen yetishmovchiligi (Leydig hujayralari funksiyasi buzilishi) kuzatiladi."},
{"savol":"Varikoselening eng ko'p uchraydigan klinik kechishi qanday?","variantlar":["Kuchli, chidab bo'lmas darajadagi og'riq bilan","Asimptomatik — hech qanday sezilarli belgisiz","Yuqori isitma, terlash va qaltirash bilan","Doimiy qon ketishi (gematuriya) bilan birga"],"togri":1,"izoh":"Ko'pchilik bemorlarda varikosele asimptomatik kechadi va tasodifan yoki infertillik tekshiruvi jarayonida aniqlanadi."},
{"savol":"Varikoseleda og'riq odatda qachon kuchayadi va qachon kamayadi?","variantlar":["Yotganda kuchayadi, tik turgan holatda esa kamayadi","Uzoq tik turish/zo'riqishdan keyin kuchayib, yotganda kamayadi","Faqat tunda uyqu paytida kuchayadigan o'ziga xos og'riq","Faqat ovqatlanishdan so'ng paydo bo'lib kuchayadigan og'riq"],"togri":1,"izoh":"Mosjonkadagi og'riq uzoq tik turish yoki jismoniy zo'riqishdan keyin kuchayadi, yotgan holatda kamayadi."},
{"savol":"'Qurt to'plami' (bag of worms) ko'rinishi qaysi darajadagi varikoseleda kuzatiladi?","variantlar":["Subklinik (yashirin) daraja","I-daraja (yengil shakl)","II-daraja (o'rtacha shakl)","Og'ir III-daraja (yirik shakl)"],"togri":3,"izoh":"Og'ir (III) darajali varikoselede ko'zga ko'rinadigan venalar to'plami 'qurt to'plami' ko'rinishini hosil qiladi."},
{"savol":"Varikoseleni fizik tekshirishda bemor nega issiq xonada va tik turgan holatda tekshiriladi?","variantlar":["Bu shart emas — istalgan holat va sharoitda tekshirsa bo'ladi","Sovuqda kremaster qisqarib varikoseleni yashirishi mumkin","Issiq xona qon bosimini oshirib natijani aniqlashtiradi","Faqat bemorning qulayligi va tinchligini ta'minlash uchun"],"togri":1,"izoh":"Sovuq sharoitda kremaster mushagi qisqaradi va moyakni ko'taradi, bu varikoseleni yashirib, noto'g'ri (yolg'on negativ) natijaga olib kelishi mumkin."},
{"savol":"Erkaklar reproduktologiya bo'limiga murojaat qilishning eng ko'p sababi nima?","variantlar":["Moshonka sohasidagi og'riq","Infertillik (bepushtlik)","Moshonkaning shishi","Teri qichishishi va toshma"],"togri":1,"izoh":"Infertillik — varikoseleli erkaklarning reproduktologga murojaat qilishining eng ko'p uchraydigan sababi."},
{"savol":"Klinik eslatmaga ko'ra, varikoseleni to'g'ri aniqlash uchun bemorni qanday tekshirish zarur?","variantlar":["Faqat gorizontal yotgan holatda tekshirib ko'rish orqali","Tik turgan holatda va Valsalva sinamasi bilan tekshirib","Faqat chuqur uyqu (uxlagan) holatida tekshirib ko'rish orqali","Faqat oddiy rentgen tasviri asosida baholab aniqlash orqali"],"togri":1,"izoh":"Kichik varikoseleler yotgan holatda osongina o'tkazib yuborilishi mumkin, shu sabab bemor albatta tik turgan holatda va Valsalva sinamasi bilan tekshirilishi kerak."},
{"savol":"Varikoselening diagnostikasida birinchi navbatdagi asosiy usul qaysi?","variantlar":["Kompyuter tomografiya (KT)","Magnit-rezonans tomografiya (MRT)","Klinik diagnoz — fizik tekshiruv","Genomik va molekulyar tekshiruv"],"togri":2,"izoh":"Varikoselening diagnostikasi birinchi navbatda klinik diagnoz hisoblanadi — fizik tekshiruv (ko'rish va palpatsiya) asosiy usul."},
{"savol":"Mosjonka Doppler ultratovush tekshiruvi qaysi chastotali datchiklar yordamida o'tkaziladi?","variantlar":["1-3 MHz","7.5-10 MHz","20-25 MHz","0.5-1 MHz"],"togri":1,"izoh":"Mosjonka Doppler UTT yuqori chastotali (7.5-10 MHz) datchiklar yordamida o'tkaziladi."},
{"savol":"Doppler UTT qaysi holatda ko'rsatma hisoblanadi?","variantlar":["Har doim, eng birinchi tanlov diagnostik usul sifatida","Klinik tekshiruv noaniq bo'lganda yoki qoldiq/retsidivda","Faqat go'dak va o'smir yoshdagi bolalarda qo'llaniladi","Faqat ayol jinsi vakillarini tekshirishda qo'llaniladi"],"togri":1,"izoh":"UTT klinik tekshiruv noaniq bo'lganda (masalan, lipoma tufayli) va jarrohlikdan keyin qoldiq yoki qaytalangan varikoseleni baholash uchun ko'rsatma hisoblanadi."},
{"savol":"Yo'naltiruvchi tavsiyaga ko'ra, varikoseleni UTT'da aniqlash uchun vena diametri bo'yicha qanday holat mavjud?","variantlar":["Aniq, xalqaro miqyosda qabul qilingan chegara qiymati bor","Yagona universal chegara qiymati yo'q — bu munozarali masala","Faqat 1 mm dan katta bo'lgandagina varikosele hisoblanadi","Vena diametri diagnostikada umuman ahamiyatga ega emas"],"togri":1,"izoh":"Varikoselening UTT'da aniqlanishi uchun vena diametri bo'yicha yagona, universal qabul qilingan chegara qiymati mavjud emas — bu adabiyotlarda hali munozarali."},
{"savol":"Kompyuter tomografiya (KT) varikosele diagnostikasida qanday o'rin tutadi?","variantlar":["Varikosele uchun eng birinchi tanlanadigan asosiy usul","Birinchi tanlov emas, ammo chov sohasi patologiyasida foydali","Varikosele diagnostikasida umuman qo'llanilmaydigan usul","Faqat go'dak va bolalar diagnostikasida qo'llaniladigan usul"],"togri":1,"izoh":"KT odatda birinchi tanlov usuli emas, lekin chov sohasi va urug' tizimchasi patologiyasini baholashda foydali bo'lishi mumkin."},
{"savol":"MRT varikosele diagnostikasida qachon qo'llaniladi?","variantlar":["Har doim eng birinchi navbatdagi tanlov usuli sifatida","Noaniq UTT topilmalarida ikkinchi qatorli tasvirlash usuli","Faqat varikoselektomiya jarrohligidan bevosita oldin","Hech qanday holatda umuman qo'llanilmaydigan usul sifatida"],"togri":1,"izoh":"MRT noaniq ultratovush topilmalarida ikkinchi qatorli tasvirlash usuli sifatida qo'llaniladi."},
{"savol":"Venografiya asosan qachon qo'llaniladi?","variantlar":["Eng birinchi navbatdagi skrining usuli sifatida keng","Radiologik embolizatsiyadan oldin/davomida davolash maqsadida","Faqat go'dak va o'smir bolalar diagnostikasida keng","Klinik amaliyotda hech qachon qo'llanilmaydigan eskirgan usul"],"togri":1,"izoh":"Venografiya asosan radiologik embolizatsiyadan oldin yoki uning davomida diagnostik/davolash maqsadida qo'llaniladi."},
{"savol":"Serum testosteron darajasi qancha bo'lganda gipoandrogenizm haqida gap boradi?","variantlar":["280-300 ng/dL dan past bo'lganda","1000 ng/dL dan yuqori bo'lganda","50 ng/dL dan ham past bo'lganda","Har qanday qiymatda, farqsiz"],"togri":0,"izoh":"Odatda serum testosteron darajasi 280-300 ng/dL dan past bo'lsa, gipoandrogenizm (androgen yetishmovchiligi) haqida gap boradi."},
{"savol":"Gidroselening varikoseledan asosiy farqlovchi belgisi nima?","variantlar":["Transilluminatsiya pozitiv — yorug'likni o'tkazib yuboradi","Faqat Valsalva sinamasi paytida paydo bo'lib qoladi xolos","Venalarning buralgan to'plami (qurt to'plami) ko'rinishida","Faqat tananing chap tomonida izolyatsiyalangan holda uchraydi"],"togri":0,"izoh":"Gidrosele suyuqlik to'plami bo'lgani uchun transilluminatsiya (yorug'lik o'tkazish) pozitiv bo'ladi va venalar tugunchasi bo'lmaydi — bu varikoseledan asosiy farqi."},
{"savol":"Subklinik varikoseleda qanday yondashuv tavsiya etiladi?","variantlar":["Zudlik bilan jarrohlik aralashuvi","Dinamik kuzatuv (jarrohliksiz)","Doimiy uzoq antibiotikoterapiya","Radiologik embolizatsiya qilish"],"togri":1,"izoh":"Subklinik varikosele (faqat instrumental usulda aniqlangan) holatida faol jarrohlik aralashuvisiz dinamik kuzatuv tavsiya etiladi."},
{"savol":"O'smirlarda varikosele kuzatuvi qancha muddatda o'tkaziladi (agar urug' bezi hajmi normal bo'lsa)?","variantlar":["Har hafta muntazam ravishda takroriy tekshirish orqali","Har 6-12 oyda orkidometriya/UTT bilan kuzatib borish orqali","Faqat bir marta tekshirilib, keyin kuzatuv talab etilmaydi","Har kuni ertalab muntazam o'z-o'zini tekshirish orqali"],"togri":1,"izoh":"O'smirlarda, agar urug' bezi hajmi va o'sishi normal bo'lsa, har 6-12 oyda orkidometriya/UTT bilan muntazam kuzatuv maqsadga muvofiq."},
{"savol":"Varikoselening o'zini bartaraf etish bo'yicha qaysi fikr to'g'ri?","variantlar":["Samarali dori vositasi bor, faqat erta boshlash muhim","Samarali dori yo'q — bu anatomik/jarrohlik muammosidir","Faqat uzoq muddatli antibiotik terapiyasi bilan tuzaladi","Aksariyat hollarda o'z-o'zidan mustaqil ravishda tuzaladi"],"togri":1,"izoh":"Varikoselening o'zini bartaraf etish uchun samarali dori vositasi mavjud emas — bu faqat anatomik/jarrohlik muammosi hisoblanadi."},
{"savol":"Jarrohlik (varikoselektomiya) uchun asosiy ko'rsatmalardan biri qaysi?","variantlar":["Faqat estetik (tashqi ko'rinishni yaxshilash) maqsadida","Klinik varikosele + patologik spermogramma + bola istagi","Bemorning yoshi 18 dan oshib qolganligining o'zi yetarli","Varikoselening faqat o'ng tomonda joylashganligi asosida"],"togri":1,"izoh":"Asosiy ko'rsatmalardan biri — klinik (palpatsiya bilan aniqlanadigan) varikosele, patologik spermogramma ko'rsatkichlari va er-xotinning bola ko'rishga intilishi birikmasi."},
